class ComplianceReportGenerator:
    """
    Evidence-backed compliance and security audit report generator.
    Strictly separates empirically measured controls from unverified requirements.
    """

    @classmethod
    def generate_report(
        cls,
        db: Session,
        user_id: str,
        agent_id: Optional[str] = None,
        framework: str = "OWASP_LLM_TOP_10",
        title: Optional[str] = None
    ) -> ComplianceReport:
        framework_key = framework.upper()
        if framework_key not in FRAMEWORK_DEFINITIONS:
            framework_key = "OWASP_LLM_TOP_10"

        framework_meta = FRAMEWORK_DEFINITIONS[framework_key]
        agent = None
        if agent_id:
            agent = db.query(Agent).filter(Agent.id == agent_id).first()

        report_title = title or f"{framework_meta['name']} Compliance Report — {agent.name if agent else 'All Agents'}"

        # Fetch recent security test executions for agent(s)
        test_query = db.query(SecurityTest).filter(SecurityTest.user_id == user_id)
        if agent_id:
            test_query = test_query.filter(SecurityTest.agent_id == agent_id)
        recent_tests = test_query.order_by(desc(SecurityTest.created_at)).limit(10).all()
        test_ids = [t.id for t in recent_tests]

        # Fetch all executions and findings
        executions = db.query(TestExecution).filter(TestExecution.test_id.in_(test_ids)).all() if test_ids else []
        findings = db.query(VulnerabilityFinding).filter(VulnerabilityFinding.test_id.in_(test_ids)).all() if test_ids else []

        # Map executions and findings to controls
        controls_evaluated = []
        measured_controls = []
        unverified_controls = []

        total_controls = len(framework_meta["controls"])
        compliant_controls_count = 0

        for ctrl in framework_meta["controls"]:
            ctrl_id = ctrl["id"]
            ctrl_cat = ctrl.get("category", "")

            # Find matching executions by category
            matching_execs = [
                e for e in executions
                if e.scenario and (e.scenario.category == ctrl_cat or ctrl_cat in ("general", "testing", "threat_mapping", "mitigation"))
            ]
            matching_findings = [
                f for f in findings
                if f.category == ctrl_cat or (f.scenario and f.scenario.category == ctrl_cat)
            ]

            if matching_execs or matching_findings:
                # This is an EMPIRICALLY MEASURED control
                exploited_count = sum(1 for e in matching_execs if getattr(e, "result", "") == "vulnerable")
                blocked_count = sum(1 for e in matching_execs if getattr(e, "result", "") in ("blocked", "passed"))
                is_compliant = (exploited_count == 0 and len(matching_findings) == 0)

                if is_compliant:
                    compliant_controls_count += 1

                control_record = {
                    "control_id": ctrl_id,
                    "title": ctrl["title"],
                    "description": ctrl["description"],
                    "verification_type": "MEASURED_EMPIRICAL",
                    "status": "PASS" if is_compliant else "FAIL",
                    "evidence_executions_count": len(matching_execs),
                    "active_vulnerabilities_count": len(matching_findings),
                    "blocked_attempts_count": blocked_count,
                    "finding_ids": [f.id for f in matching_findings],
                    "details": f"Evaluated against {len(matching_execs)} test executions. Blocked: {blocked_count}, Exploits: {exploited_count}."
                }
                measured_controls.append(control_record)
                controls_evaluated.append(control_record)
            else:
                # This is an UNVERIFIED control (no test executions covering it)
                unverified_record = {
                    "control_id": ctrl_id,
                    "title": ctrl["title"],
                    "description": ctrl["description"],
                    "verification_type": "UNVERIFIED_INSUFFICIENT_TEST_DATA",
                    "status": "NOT_TESTED",
                    "evidence_executions_count": 0,
                    "active_vulnerabilities_count": 0,
                    "details": "No active test executions recorded for this control category. Run targeted test scenarios to measure this control."
                }
                unverified_controls.append(unverified_record)
                controls_evaluated.append(unverified_record)

        # Calculate compliance percentage over measured controls
        measured_total = len(measured_controls)
        compliance_pct = round((compliant_controls_count / measured_total * 100), 1) if measured_total > 0 else 0.0

        summary_text = (
            f"Assessment evaluated {len(controls_evaluated)} framework controls for {agent.name if agent else 'enterprise agents'}. "
            f"{len(measured_controls)} controls were empirically measured with reproducible test executions, "
            f"and {len(unverified_controls)} controls remain unverified due to lack of test data. "
            f"Empirical compliance rating: {compliance_pct}%."
        )

        report = ComplianceReport(
            user_id=user_id,
            agent_id=agent_id,
            title=report_title,
            framework=framework_key,
            summary=summary_text,
            score={
                "measured_compliance_percentage": compliance_pct,
                "measured_controls_count": len(measured_controls),
                "unverified_controls_count": len(unverified_controls),
                "compliant_controls_count": compliant_controls_count,
                "total_findings_count": len(findings),
            },
            controls_evaluated=controls_evaluated,
            measured_controls=measured_controls,
            unverified_controls=unverified_controls,
            findings=[f.to_dict() for f in findings[:20]],
            compliance_percentage=f"{compliance_pct}%",
            certification_disclaimer=CERTIFICATION_DISCLAIMER,
            created_at=datetime.utcnow()
        )
        db.add(report)
        db.commit()
        db.refresh(report)

        return report

    @classmethod
    def get_reports(
        cls,
        db: Session,
        user_id: str,
        agent_id: Optional[str] = None
    ) -> List[ComplianceReport]:
        query = db.query(ComplianceReport).filter(ComplianceReport.user_id == user_id)
        if agent_id:
            query = query.filter(ComplianceReport.agent_id == agent_id)
        return query.order_by(desc(ComplianceReport.created_at)).all()

    @classmethod
    def get_report(cls, db: Session, report_id: str, user_id: str) -> Optional[ComplianceReport]:
        return db.query(ComplianceReport).filter(
            ComplianceReport.id == report_id,
            ComplianceReport.user_id == user_id
        ).first()
